-- =====================================================================
-- Persona Fit — enriquecimento do catálogo de exercícios
--
-- +251 exercícios: de 271 para 522. Fonte: yuhonas/free-exercise-db
-- (CC0), a mesma que já alimenta as imagens do catálogo — então todos
-- nascem COM as duas imagens de demonstração.
--
-- Critérios de seleção, nesta ordem:
--   1. Nada de nível `expert` (decisão do dev).
--   2. Kettlebell completo (decisão do dev).
--   3. Near-duplicatas descartadas na mão: 63 candidatos caíram por serem
--      variação de pegada/lateralidade do mesmo movimento (seis roscas de
--      punho, quatro flexões inclinadas, três extensões de tríceps
--      curvado...). Quantidade sem variedade real pioraria o prompt da IA,
--      que recebe só 8 exercícios por grupo.
--   4. Nenhum nome colide com o catálogo existente (validado antes de gerar).
--
-- Nomes em PT-BR seguindo a convenção "<Nome> (<equipamento>)" já usada. O
-- termo que não se traduz fica em inglês, com o português quando existe —
-- "Bom dia pernas estendidas (good morning)".
--
-- `requires_lower_limbs` classificado por músculo primário + categoria, com
-- 19 correções manuais para movimentos que usam a perna como apoio ou
-- alavanca sem citá-la no nome (sit-up, superman, prancha caminhando).
--
-- Idempotente: `on conflict ... do nothing` sobre o índice parcial do seed.
-- =====================================================================

do $$
declare
  g_back uuid;
  g_biceps uuid;
  g_cardio uuid;
  g_chest uuid;
  g_core uuid;
  g_full_body uuid;
  g_legs uuid;
  g_shoulders uuid;
  g_triceps uuid;
begin
  select id into g_back from public.exercise_groups where slug = 'back';
  select id into g_biceps from public.exercise_groups where slug = 'biceps';
  select id into g_cardio from public.exercise_groups where slug = 'cardio';
  select id into g_chest from public.exercise_groups where slug = 'chest';
  select id into g_core from public.exercise_groups where slug = 'core';
  select id into g_full_body from public.exercise_groups where slug = 'full_body';
  select id into g_legs from public.exercise_groups where slug = 'legs';
  select id into g_shoulders from public.exercise_groups where slug = 'shoulders';
  select id into g_triceps from public.exercise_groups where slug = 'triceps';

  on conflict (group_id, name) where owner_id is null do nothing;
end $$;
